import random
from typing import Tuple

def _pgm_p5(width: int, height: int, maxval: int, pixels: bytes) -> bytes:
    # Binary PGM (P5)
    header = f"P5\n{width} {height}\n{maxval}\n".encode("ascii")
    return header + pixels

def _ppm_p6(width: int, height: int, maxval: int, pixels: bytes) -> bytes:
    # Binary PPM (P6)
    header = f"P6\n{width} {height}\n{maxval}\n".encode("ascii")
    return header + pixels

def _pgm_p2(width: int, height: int, maxval: int, values: Tuple[int, ...]) -> bytes:
    # ASCII PGM (P2)
    # Write a reasonably spaced ASCII representation
    header = f"P2\n{width} {height}\n{maxval}\n".encode("ascii")
    body_parts = []
    per_line = max(1, 16 // (len(str(maxval)) + 1))
    count = 0
    line = []
    for v in values:
        line.append(str(v))
        count += 1
        if count % per_line == 0:
            body_parts.append(" ".join(line))
            line = []
    if line:
        body_parts.append(" ".join(line))
    body = ("\n".join(body_parts) + "\n").encode("ascii")
    return header + body

def _gen_dims(rng: random.Random) -> Tuple[int, int]:
    # Choose small but varied dimensions to exercise alignment/stride logic
    choices = [(1,1),(2,1),(1,2),(2,2),(3,2),(2,3),(4,4),(8,3),(3,8)]
    if rng.random() < 0.4:
        return rng.choice(choices)
    # Occasionally pick random small dims
    w = rng.randint(1, 16)
    h = rng.randint(1, 16)
    return w, h

def _gen_maxval(rng: random.Random, binary: bool) -> int:
    # For 8-bit loader: maxval must be 255 for P5/P6. ASCII P2 can be <= 255.
    if binary:
        return 255
    # Favor 255 but sometimes pick other legal values
    if rng.random() < 0.7:
        return 255
    return rng.choice([3, 7, 15, 31, 63, 127, 200, 250])

def _gen_gray_pixels(rng: random.Random, count: int, maxval: int, binary: bool) -> bytes:
    if binary:
        # bytes per pixel = 1 for maxval<=255
        return bytes(rng.getrandbits(8) % (maxval + 1) for _ in range(count))
    else:
        # For ASCII we will return values separately; not used here
        raise NotImplementedError

def _gen_rgb_pixels(rng: random.Random, count: int, maxval: int) -> bytes:
    # count is number of pixels; 3 bytes per pixel for P6 with maxval 255
    # Constrain to 0..maxval
    data = bytearray()
    for _ in range(count):
        r = rng.randrange(maxval + 1)
        g = rng.randrange(maxval + 1)
        b = rng.randrange(maxval + 1)
        data.extend((r, g, b))
    return bytes(data)

def _choose_format(rng: random.Random):
    # Choose among PGM binary (P5), PGM ASCII (P2), PPM binary (P6)
    # PGM P5 guaranteed to be supported by both stubs; include others for coverage
    return rng.choices(["P5", "P2", "P6"], weights=[0.55, 0.2, 0.25], k=1)[0]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    fmt = _choose_format(rng)
    w, h = _gen_dims(rng)

    if fmt == "P5":
        maxval = _gen_maxval(rng, binary=True)
        pixels = _gen_gray_pixels(rng, w * h, maxval, binary=True)
        return _pgm_p5(w, h, maxval, pixels)

    elif fmt == "P6":
        # Only valid for 8-bit loader; use maxval 255
        maxval = 255
        pixels = _gen_rgb_pixels(rng, w * h, maxval)
        return _ppm_p6(w, h, maxval, pixels)

    else:  # P2 ASCII PGM
        maxval = _gen_maxval(rng, binary=False)
        # Generate integer pixel values within 0..maxval
        values = tuple(rng.randrange(maxval + 1) for _ in range(w * h))
        return _pgm_p2(w, h, maxval, values)
